    try {
        tracker.addLabel(ticketKey, 'agent:rework');
        console.log('✅ Armed agent:rework on', ticketKey, '— SM will dispatch the rework leg');
        return true;
    } catch (e2) {
        console.warn('⚠️ Failed to arm agent:rework:', e2.message || e2);
        return false;
