function parsePRInfoMarkdown(prInfo, prAnchor) {
    var info = {};
    if (!prInfo) return info;
    var numberMatch = prInfo.match(/\*\*PR #\*\*:\s*(\d+)/);
    var urlMatch = prInfo.match(/\*\*URL\*\*:\s*(https:\/\/[^\s]+)/);
    var branchMatch = prInfo.match(/\*\*Branch\*\*:\s*([^\s\n]+)/);
    if (numberMatch) info.prNumber = parseInt(numberMatch[1], 10);
    if (urlMatch) info.prUrl = urlMatch[1];
    if (branchMatch) info.prBranch = branchMatch[1];
    if (prAnchor) {
        var authorMatch = prInfo.match(/\*\*Author\*\*:\s*([^\s\n]+)/);
        if (authorMatch) info.prAuthor = authorMatch[1];
    }
    return info;
}
