function parsePRAnchor(params, jp) {
    var folderKey = String(((params && params.inputFolderPath) || '').split('/').pop() || '');
    var anchorMatch = /^pr-(\d+)$/.exec(folderKey);
    var prAnchor = (anchorMatch ? parseInt(anchorMatch[1], 10) : null) ||
