                '+++ b/foo.js\n' +
                '@@ -2,2 +2,1 @@ function greet() {\n' +
                ' \tconst a = 1;\n' +
                '-\tconst unused = 2;\n';

            var info = mod.parseDiffLineInfo(diffText, 'foo.js', 3);

            assert.equal(info.present, true);
            assert.equal(info.side, 'LEFT', 'a pure removal with no matching added line must still resolve to LEFT');
        });
    });
});


