function normalizeRecommendation(reviewData) {
    return String((reviewData && (reviewData.recommendation || reviewData.verdict)) || 'REQUEST_CHANGES')
        .replace(/^APPROVED$/, 'APPROVE');
}
```
Original: `(reviewData.recommendation || reviewData.verdict || 'REQUEST_CHANGES').replace(...)`. `reviewData` is guaranteed non-null at that point. Keep exact. Since `.replace` requires a string — original assumes string. Keep same (no String() wrap — actually original doesn't wrap; if recommendation were a number, .replace would throw. Preserve exact behaviour: don't add String()).

- decideApproval:
```js
function normalizeIssueCounts(reviewData) {
    return reviewData.issueCounts || { blocking: 0, important: 0, suggestions: 0 };
}

function hasAnyOpenIssue(issueCounts) {
    return (issueCounts.blocking || 0) > 0 ||
           (issueCounts.important || 0) > 0 ||
           (issueCounts.suggestions || 0) > 0;
}

/**
 * The effective approval decision: the agent's APPROVE verdict stands unless
 * open issues override it (allowApproveWithSuggestions or the thread-limit
 * safety valve re-enable it).
 */
function decideApproval(recommendation, issueCounts, customParams, forceApproveDueToThreadLimit) {
    var allowApproveWithSuggestions = !!(customParams && customParams.allowApproveWithSuggestions === true);
    var hasOpenIssues = hasAnyOpenIssue(issueCounts);
    var isApproved = recommendation === 'APPROVE' &&
        (!hasOpenIssues || allowApproveWithSuggestions || forceApproveDueToThreadLimit);
    return {
        hasOpenIssues: hasOpenIssues,
        allowApproveWithSuggestions: allowApproveWithSuggestions,
        isApproved: isApproved
    };
}
