```js
// ═══ gh-926: characterization + extracted-pipeline tests ═══

/**
 * Instrumented action() harness: every observable touchpoint (scm calls,
 * tracker tools, autoStart triggers, github/bitrise bridges, token usage)
 * appends to one ordered op log, so tests can pin the exact side-effect
 * sequence — the acceptance for the gh-926 flattening is "same effects in
 * the same order".
 */
function loadReviewActionHarness(opts) {
    opts = opts || {};
