            [777, 888]
        );
        assert.equal(h.opsOf('scm.addComment').length, 2, 'general comment + verdict record');
        assert.contains(h.opsOf('scm.addComment')[0].body, 'Automated Code Review', 'general comment resolved from the file');
    });
});

