            const pr = gh.findPRForTicket(scm, ticketKey, prSearchOptions);
            if (pr) {
                prNumber = pr.number;
                prUrl = pr.html_url;
                prBranch = pr.head && pr.head.ref ? pr.head.ref : null;
                console.log('Found PR via GitHub search: #' + prNumber);
