                            config: config,
                            configFile: tcg.configFile,
                            workflowFile: tcg.workflow || 'ai-teammate.yml',
                            scm: scm
                        });
                        if (!tcgStarted) {
                            console.log('ℹ️ TestCasesGenerator not started for', ticketKey,
                                '[config=' + tcg.configFile + ']');
                        } else {
