    }

    try {
        var scm = scmModule.createScm(config);
        autoStart.triggerSmIfIdle({ config: config, customParams: customParams, scm: scm });
    } catch (e) {
        console.warn('Could not trigger SM after missing review output:', e);
    }

    return {
        success: true,
