                    if (alreadyGenerated) {
                        console.log('ℹ️ TestCasesGenerator skipped — label "' + LABELS.AI_TESTS_GENERATED + '" already present on ' + ticketKey + ' (tests generated in a previous cycle)');
                    } else if (aiOwner && aiRepo) {
