                                console.log('✅ Added label "' + LABELS.AI_TESTS_GENERATED + '" to ' + ticketKey);
                            } catch (labelErr) {
                                console.warn('⚠️ Could not add ai_tests_generated label:', labelErr.message || labelErr);
                            }
                        }
                    } else {
