    '(function(module, exports, require) {\n' + preamble + code + '\n})',
    { filename: path.resolve(process.cwd(), modulePath.replace(/^agents\//, '')) }
);
var fn = script.runInThisContext();
fn(_testModule_, _testModule_.exports, _testRequire_);
```

