  if (existsSync(lcovPath)) {
    const content = readFileSync(lcovPath, 'utf8');
    return parseLcov(content, sourceFiles);
  }

  // HTML fallback
  if (existsSync(coverageDir)) {
    return parseHtmlFallback(coverageDir);
  }

  return new Map();
}

