  const crap = loadPackageJson()?.crap ?? {};
  const {
    coverageCommand = defaults.coverageCommand,
    coverageDir = defaults.coverageDir,
    sourceGlob = defaults.sourceGlob,
  } = crap;

  return { coverageCommand, coverageDir, sourceGlob };
}

