    return dispatchParsedLine(st, line, lineNumber);
}

function applyHunkHeader(st, line) {
    var hunk = line.match(/^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/);
    if (!hunk) return false;
    st.oldLine = parseInt(hunk[1], 10);
    st.newLine = parseInt(hunk[2], 10);
