        if (line.indexOf('+++ b/') === 0) {
            currentFile = line.substring('+++ b/'.length);
            continue;
        }
        if (line.indexOf('+++ /dev/null') === 0) {
            // Deleted files have +++ /dev/null; use the old path so comments can be anchored.
            currentFile = oldFile;
            continue;
        }

